def sort_list(numbers):
    """Sorts a list of numbers in ascending order."""
    return sorted(numbers)

def get_middle_index(length):
    """Calculates the middle index for a list."""
    return length // 2

def is_even_length(length):
    """Checks if the length of a list is an even number."""
    return length % 2 == 0

def calculate_even_median(sorted_numbers, mid):
    """Calculates the median for a list with an even number of elements."""
    return (sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2

def calculate_odd_median(sorted_numbers, mid):
    """Calculates the median for a list with an odd number of elements."""
    return sorted_numbers[mid]

def calculate_median(numbers):
    """
    Calculates the median of a list of numbers.

    For an even number of elements, the average of the two middle numbers is taken.
    """
    if not numbers:
        raise ValueError("Input list cannot be empty.")

    sorted_numbers = sort_list(numbers)
    n = len(sorted_numbers)
    mid = get_middle_index(n)

    if is_even_length(n):
        return calculate_even_median(sorted_numbers, mid)
    else:
        return calculate_odd_median(sorted_numbers, mid)

