    """
    Reverses the order of words in a given sentence.

    Args:
        sentence: The input string representing a sentence.

    Returns:
        A new string with the order of words reversed.
    """
    words = split_words(sentence)
    reverse_list_in_place(words)
    reversed_sentence = join_words(words)
    return reversed_sentence

